"\377\377\377\377\377\377\377\377\213\025\000\000\000\000\000\000# gdb pretty-printers for brine prog"
"rams. `brine debug` writes this file next\012# to the debug build and loads it; by hand: `source bri"
"ne-gdb.py` in gdb.\012# Values print the way brine prints them: \042hello\042, [1, 2, 3], (1, \042tw"
"o\042),\012# {\042k\042: 9}, Shape.Rect(w=2, h=3), Some(5).\012import gdb\012\012# at most this many"
" elements or bytes of a value are shown\012LIMIT = 200\012\012\012def _fmt(v):\012    try:\012      "
"  return v.format_string()\012    except gdb.error:\012        return \042<invalid>\042\012\012\012d"
"ef _ptr(v):\012    try:\012        p = int(v)\012    except gdb.error:\012        return None\012   "
" return p if p != 0 else None\012\012\012class StrPrinter:\012    def __init__(self, v):\012        "
"self.v = v\012\012    def to_string(self):\012        if _ptr(self.v) is None:\012            return"
" \042<null>\042\012        try:\012            s = self.v.dereference()\012            n = int(s[\042"
"len\042])\012            if n < 0 or n > 1 << 40:\012                return \042<invalid>\042\012   "
"         addr = int(s[\042data\042].address)\012            data = bytes(gdb.selected_inferior().rea"
"d_memory(addr, min(n, LIMIT)))\012        except (gdb.error, gdb.MemoryError):\012            return"
" \042<invalid>\042\012        t = data.decode(\042utf-8\042, \042replace\042)\012        out = ['\042"
"']\012        for c in t:\012            if c == '\042' or c == \042\134\134\042:\012               "
" out.append(\042\134\134\042 + c)\012            elif c == \042\134n\042:\012                out.app"
"end(\042\134\134n\042)\012            elif c == \042\134t\042:\012                out.append(\042\134"
"\134t\042)\012            elif c == \042\134r\042:\012                out.append(\042\134\134r\042)\012"
"            elif ord(c) < 32:\012                out.append(\042\134\134x%02x\042 % ord(c))\012     "
"       else:\012                out.append(c)\012        out.append('\042')\012        if n > LIMIT:"
"\012            out.append(\042...\042)\012        return \042\042.join(out)\012\012\012def _items(p"
", n):\012    k = min(n, LIMIT)\012    out = [_fmt(p[i]) for i in range(k)]\012    if n > k:\012     "
"   out.append(\042...\042)\012    return out\012\012\012class ArrPrinter:\012    def __init__(self, "
"v):\012        self.v = v\012\012    def to_string(self):\012        if _ptr(self.v) is None:\012   "
"         return \042<null>\042\012        try:\012            a = self.v.dereference()\012          "
"  n = int(a[\042len\042])\012            if n < 0 or n > int(a[\042cap\042]):\012                ret"
"urn \042<invalid>\042\012            return \042[\042 + \042, \042.join(_items(a[\042data\042], n)) "
"+ \042]\042\012        except (gdb.error, gdb.MemoryError):\012            return \042<invalid>\042\012"
"\012\012class MapPrinter:\012    def __init__(self, v):\012        self.v = v\012\012    def to_stri"
"ng(self):\012        if _ptr(self.v) is None:\012            return \042<null>\042\012        try:\012"
"            m = self.v.dereference()\012            used = int(m[\042used\042])\012            if us"
"ed < 0 or used > int(m[\042cap\042]):\012                return \042<invalid>\042\012            out"
" = []\012            for i in range(used):\012                if len(out) == LIMIT:\012             "
"       out.append(\042...\042)\012                    break\012                if bool(m[\042live\042"
"][i]):\012                    out.append(_fmt(m[\042keys\042][i]) + \042: \042 + _fmt(m[\042vals\042"
"][i]))\012            return \042{\042 + \042, \042.join(out) + \042}\042\012        except (gdb.err"
"or, gdb.MemoryError):\012            return \042<invalid>\042\012\012\012class TuplePrinter:\012    "
"def __init__(self, v):\012        self.v = v\012\012    def to_string(self):\012        fs = self.v."
"type.strip_typedefs().fields()\012        out = [_fmt(self.v[f.name]) for f in fs]\012        if len"
"(out) == 1:\012            return \042(\042 + out[0] + \042,)\042\012        return \042(\042 + \042"
", \042.join(out) + \042)\042\012\012\012class BoxPrinter:\012    # v: a pointer to a box, or (inline"
") the enum value itself\012    def __init__(self, v, inline=False):\012        self.v = v\012       "
" self.inline = inline\012\012    def to_string(self):\012        if not self.inline and _ptr(self.v)"
" is None:\012            return \042<null>\042\012        try:\012            b = self.v if self.inl"
"ine else self.v.dereference()\012            label = _fmt(b[\042tag\042])\012            name = labe"
"l.rsplit(\042.\042, 1)[-1]\012            u = b[\042variant\042]\012            if name not in [f.na"
"me for f in u.type.strip_typedefs().fields()]:\012                return label\012            var = "
"u[name]\012            fs = var.type.strip_typedefs().fields()\012            if \042.\042 in label:"
"\012                args = [f.name + \042=\042 + _fmt(var[f.name]) for f in fs]\012            else:"
"\012                # Option and Result print their payload alone\012                args = [_fmt(va"
"r[f.name]) for f in fs]\012            return label + \042(\042 + \042, \042.join(args) + \042)\042\012"
"        except (gdb.error, gdb.MemoryError):\012            return \042<invalid>\042\012\012\012clas"
"s BytePrinter:\012    def __init__(self, v):\012        self.v = v\012\012    def to_string(self):\012"
"        return str(int(self.v))\012\012\012def lookup(v):\012    t = v.type\012    name = t.name\012"
"    if name is None:\012        return None\012    if name == \042str\042:\012        return StrPrin"
"ter(v)\012    if name in (\042u8\042, \042i8\042):\012        return BytePrinter(v)\012    if name.s"
"tartswith(\042[\042):\012        return ArrPrinter(v)\012    if name.startswith(\042{\042):\012     "
"   return MapPrinter(v)\012    if name.startswith(\042(\042):\012        return TuplePrinter(v)\012 "
"   t = t.strip_typedefs()\012    if t.code == gdb.TYPE_CODE_PTR:\012        target = t.target()\012 "
"       if target.tag is not None and target.tag.startswith(\042brine_box \042):\012            retur"
"n BoxPrinter(v)\012    if t.code == gdb.TYPE_CODE_STRUCT:\012        # an enum stored inline: {tag, "
"variant}\012        fs = t.fields()\012        if len(fs) == 2 and fs[0].name == \042tag\042 and fs["
"1].name == \042variant\042:\012            tn = fs[0].type.name\012            if tn is not None and"
" tn.endswith(\042.tag\042):\012                return BoxPrinter(v, True)\012    return None\012\012"
"\012def _setup():\012    gdb.pretty_printers.append(lookup)\012    # don't step into the C runtime\012"
"    for f in (\042brine_rt.c\042, \042brine_rt.h\042):\012        gdb.execute(\042skip -gfi */\042 +"
" f, to_string=True)\012\012\012_setup()\012\000\000\000\000\000";
