"\377\377\377\377\377\377\377\377\233\005\000\000\000\000\000\000# The prelude: visible in every modu"
"le without an import.\012\012enum Option[T]:\012    Some(value: T)\012    None\012\012    fn is_some"
"(self) -> bool:\012        match self:\012            case Some(_):\012                return true\012"
"            case None:\012                return false\012\012    fn is_none(self) -> bool:\012     "
"   return not self.is_some()\012\012    fn unwrap(self) -> T:\012        match self:\012            "
"case Some(v):\012                return v\012            case None:\012                panic(\042unw"
"rap() called on None\042)\012\012    fn unwrap_or(self, default: T) -> T:\012        match self:\012"
"            case Some(v):\012                return v\012            case None:\012                r"
"eturn default\012\012enum Result[T, E]:\012    Ok(value: T)\012    Err(error: E)\012\012    fn is_ok"
"(self) -> bool:\012        match self:\012            case Ok(_):\012                return true\012"
"            case Err(_):\012                return false\012\012    fn is_err(self) -> bool:\012    "
"    return not self.is_ok()\012\012    fn unwrap(self) -> T:\012        match self:\012            c"
"ase Ok(v):\012                return v\012            case Err(e):\012                panic(f\042unw"
"rap() called on Err: {e}\042)\012\012    fn unwrap_or(self, default: T) -> T:\012        match self:"
"\012            case Ok(v):\012                return v\012            case Err(_):\012             "
"   return default\012\012    fn ok(self) -> Option[T]:\012        match self:\012            case Ok"
"(v):\012                return Some(v)\012            case Err(_):\012                return None\012"
"\000\000\000\000\000";
