"caps\012 * the choice (to test the other versions on a new machine).\012 *\012 * Floating-point resu"
"lts are the same in all three: the driver compiles\012 * with -ffp-contract=off, so multiplies and a"
"dds are never fused. */\012#include <cpuid.h>\012#include <stdint.h>\012#include <stdlib.h>\012#incl"
"ude <string.h>\012\012int brine_main_base(int argc, char **argv);\012int brine_main_v3(int argc, cha"
"r **argv);\012int brine_main_v4(int argc, char **argv);\012\012/* the register state the OS saves on"
" a thread switch (XCR0) */\012static uint64_t brine_xcr0(void) {\012    uint32_t a, d;\012    __asm_"
"_ volatile(\042xgetbv\042 : \042=a\042(a), \042=d\042(d) : \042c\042(0));\012    return ((uint64_t)d"
" << 32) | a;\012}\012\012static int brine_cpu_level(void) {\012    int cap = 4;\012    const char *e"
" = getenv(\042BRINE_CPU\042);\012    if (e && strcmp(e, \042base\042) == 0) cap = 1;\012    if (e &&"
" strcmp(e, \042v3\042) == 0) cap = 3;\012    unsigned a, b, c, d;\012    if (cap < 3 || !__get_cpuid"
"(1, &a, &b, &c, &d)) return 1;\012    /* SSE3, SSSE3, FMA, CMPXCHG16B, SSE4.1, SSE4.2, MOVBE, POPCNT"
", OSXSAVE, AVX, F16C */\012    const unsigned l1 = 1u << 0 | 1u << 9 | 1u << 12 | 1u << 13 | 1u << 1"
"9 | 1u << 20 | 1u << 22 |\012                        1u << 23 | 1u << 27 | 1u << 28 | 1u << 29;\012 "
"   if ((c & l1) != l1) return 1;\012    /* the OS saves the SSE and AVX registers */\012    if ((bri"
"ne_xcr0() & 6) != 6) return 1;\012    /* LAHF in 64-bit mode, LZCNT */\012    if (!__get_cpuid(0x800"
"00001, &a, &b, &c, &d) || (c & 0x21) != 0x21) return 1;\012    /* BMI1, AVX2, BMI2 */\012    if (!__"
"get_cpuid_count(7, 0, &a, &b, &c, &d)) return 1;\012    const unsigned l7 = 1u << 3 | 1u << 5 | 1u <"
"< 8;\012    if ((b & l7) != l7) return 1;\012    /* AVX-512 F, DQ, CD, BW, VL, and the OS saves thei"
"r registers */\012    const unsigned v4 = 1u << 16 | 1u << 17 | 1u << 28 | 1u << 30 | 1u << 31;\012 "
"   if (cap >= 4 && (b & v4) == v4 && (brine_xcr0() & 0xe6) == 0xe6) return 4;\012    return 3;\012}\012"
"\012int main(int argc, char **argv) {\012    switch (brine_cpu_level()) {\012    case 4:\012        "
"return brine_main_v4(argc, argv);\012    case 3:\012        return brine_main_v3(argc, argv);\012   "
" default:\012        return brine_main_base(argc, argv);\012    }\012}\012\000\000\000\000\000\000\000";
