static _Alignas(8) uint8_t br_sdd02dafcfc88b02c[2168] =
"\377\377\377\377\377\377\377\377f\010\000\000\000\000\000\000// Runs a WebAssembly build of a brine "
"program under Node.js:\012//\012//     node brine_wasi.mjs program.wasm [args...]\012//\012// `brine"
" run --target wasm` and `brine test --target wasm` use it.\012import { readFile } from \042node:fs/p"
"romises\042;\012import { writeSync } from \042node:fs\042;\012import { WASI } from \042node:wasi\042"
";\012import { Worker, isMainThread, workerData } from \042node:worker_threads\042;\012import process"
" from \042node:process\042;\012\012// WebAssembly frames live on the thread's native stack, about 1 "
"MB on the\012// main thread: recursion that runs natively would trap after ~10k calls. A\012// worke"
"r thread can have a big stack.\012const STACK_MB = 256;\012\012if (isMainThread) {\012  const worker"
" = new Worker(new URL(import.meta.url), {\012    workerData: process.argv.slice(2),\012    resourceL"
"imits: { stackSizeMb: STACK_MB },\012  });\012  worker.on(\042exit\042, (code) => {\012    process.e"
"xitCode = code;\012  });\012  worker.on(\042error\042, (e) => {\012    writeSync(2, `\134nbrine: the"
" WebAssembly runner failed: ${e && e.stack \077 e.stack : e}\134n`);\012    process.exitCode = 134;\012"
"  });\012} else {\012  const [file, ...args] = workerData;\012  // paths relative to the current fol"
"der work as they do natively. Only that\012  // folder: with \042/\042 also open, wasi-libc resolves"
" relative paths under \042/\042.\012  const preopens = { \042.\042: \042.\042 };\012  const wasi = n"
"ew WASI({\012    version: \042preview1\042,\012    args: [file, ...args],\012    env: process.env,\012"
"    preopens,\012    returnOnExit: true,\012  });\012  const module = await WebAssembly.compile(awai"
"t readFile(file));\012  const instance = await WebAssembly.instantiate(module, wasi.getImportObject("
"));\012  let code = 0;\012  try {\012    code = wasi.start(instance);\012  } catch (e) {\012    // a"
" trap: what the program printed before it is still in its buffer\012    try {\012      instance.expo"
"rts.brine_flush\077.();\012    } catch {}\012    if (e instanceof RangeError) {\012      // the engi"
"ne's call stack ran out: report it as native code does\012      writeSync(2, \042\134npanic: stack o"
"verflow (recursion too deep)\134n\042);\012      code = 101;\012    } else {\012      // brine panic"
"s exit with 101, so this is a crash\012      writeSync(2, `\134nWebAssembly trap: ${e && e.message \077"
" e.message : e}\134n`);\012      code = 134;\012    }\012  }\012  process.exit(code);\012}\012\000\000";
